program='''def transform(grid):
    """Trace a beam from an edge source through gaps in 8-colored barriers."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sources = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not sources:
        return out
    r0, c0 = sources[0]
    if r0 == 0:
        axis, direction, start, limit = 0, 1, r0, h
    elif r0 == h - 1:
        axis, direction, start, limit = 0, -1, r0, -1
    elif c0 == 0:
        axis, direction, start, limit = 1, 1, c0, w
    else:
        axis, direction, start, limit = 1, -1, c0, -1

    def cell(t, y):
        return grid[t][y] if axis == 0 else grid[y][t]

    def paint(t, y):
        if axis == 0:
            if grid[t][y] != 8:
                out[t][y] = 2
        else:
            if grid[y][t] != 8:
                out[y][t] = 2

    def paint_barrier(t, y):
        if axis == 0:
            out[t][y] = 2
        else:
            out[y][t] = 2

    cross_len = w if axis == 0 else h
    active = {c0 if axis == 0 else r0}
    t = start
    while t != limit:
        next_active = set()
        for y in active:
            if cell(t, y) != 8:
                paint(t, y)
                nt = t + direction
                if nt != limit:
                    next_active.add(y)
                continue

            # The barrier blocks this ray. It travels sideways in the adjacent
            # free slice until it reaches the first opening in either direction.
            prev_t = t - direction
            for side in (-1, 1):
                yy = y
                while 0 <= yy < cross_len:
                    paint(prev_t, yy)
                    if cell(t, yy) != 8:
                        paint_barrier(t, yy)
                        nt = t + direction
                        if nt != limit:
                            next_active.add(yy)
                        break
                    yy += side
        active = next_active
        if not active:
            break
        t += direction
    return out
'''
